/* consensustest comparison report — static UI.
 *
 * Reads window.REPORT_DATA (populated by data.js — regenerated by
 * `make consensustest-report`) and renders the page. Edit freely and
 * refresh the browser; no test rerun required.
 *
 * Page structure per sweep:
 *  Section: <sweep title>
 *    Part A — Cross-protocol comparison:
 *      one <details>-collapsible chart pack per Scenario.Group.
 *    Part B — OBFT-only scenarios (at the end):
 *      one collapsible pack per group containing scenarios where QBFT
 *      is ExpectNotApplicable.
 *
 *  Each pack contains: matrix (clickable rows) + ONE interactive chart
 *  showing the selected scenario's data:
 *    - 1-point sweep  → bar chart of P50/P90/P99 decision time.
 *    - multi-point    → line chart of P99 decision time vs swept axis.
 *
 *  The first pack of each sweep is open by default; the rest are
 *  collapsed to keep the page short. Scroll-driven IntersectionObserver
 *  highlights the active sweep in the sticky TOC and exposes a
 *  per-sweep sub-row of group anchors.
 */

'use strict';

const PROTOCOL_COLORS = {
  OBFT: '#0969da',
  QBFT: '#cf222e',
};

// chartInstances / chartInits — populated during the render pass.
// chartInits runs once at the end synchronously (rAF is throttled in
// headless preview environments, which would leave charts blank).
const chartInstances = [];
const chartInits = [];

// packsBySweep keeps track of the group packs in each sweep so the
// sub-TOC can rebuild its group anchors when the active sweep changes.
const packsBySweep = {};

document.addEventListener('DOMContentLoaded', main);

function main() {
  const data = window.REPORT_DATA;
  const root = document.getElementById('root');
  if (!data) {
    return; // index.html already shows the placeholder.
  }
  applyChartDefaults();
  const bucketing = computeBuckets(data);

  root.innerHTML = '';
  root.appendChild(renderHeader(data));
  root.appendChild(renderTOC(data));
  const mainEl = h('main');
  data.sweeps.forEach((sw) => mainEl.appendChild(renderSweepSection(sw, data, bucketing)));
  root.appendChild(mainEl);
  // Chart.js sizes from .chart-wrap CSS dimensions; canvases are in the
  // DOM by the time these fire, so synchronous init is safe.
  chartInits.forEach((fn) => fn());
  setupActiveTOC(data);
}

// applyChartDefaults tweaks Chart.js globally so individual chart
// configs stay short. Lighter gridlines, friendlier tooltips, rounded
// bars, the page's typography.
function applyChartDefaults() {
  if (typeof Chart === 'undefined') return;
  Chart.defaults.font.family = '-apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif';
  Chart.defaults.font.size = 12;
  Chart.defaults.color = '#475569';
  Chart.defaults.borderColor = 'rgba(15, 23, 42, 0.06)';
  Chart.defaults.elements.bar.borderRadius = 4;
  Chart.defaults.elements.bar.borderWidth = 0;
  Chart.defaults.elements.line.tension = 0.15;
  Chart.defaults.elements.line.borderWidth = 2.5;
  Chart.defaults.elements.point.radius = 4;
  Chart.defaults.elements.point.hoverRadius = 7;
  Chart.defaults.plugins.tooltip.padding = 10;
  Chart.defaults.plugins.tooltip.cornerRadius = 6;
  Chart.defaults.plugins.tooltip.backgroundColor = 'rgba(15, 23, 42, 0.92)';
  Chart.defaults.plugins.tooltip.titleFont = { size: 12, weight: '600' };
  Chart.defaults.plugins.tooltip.bodyFont = { size: 12 };
  Chart.defaults.plugins.tooltip.boxPadding = 6;
  Chart.defaults.plugins.legend.labels.boxWidth = 12;
  Chart.defaults.plugins.legend.labels.font = { size: 12 };
}

// ---- scope + group bucketing -----------------------------------------

// computeBuckets partitions scenarios into "cross" (applies to every
// protocol in the data) and "obftOnly" (QBFT marked n/a everywhere).
// Within each scope, scenarios stay in Catalog order grouped by their
// Scenario.Group field, with first-appearance ordering of groups.
function computeBuckets(data) {
  const scopeByName = {};
  data.scenarios.forEach((sc) => {
    let hasQbft = false;
    outer: for (const sw of data.sweeps) {
      for (const pt of sw.points) {
        const cell = findCell(pt, sc.name, 'QBFT');
        if (cell && cell.iterations > 0) {
          hasQbft = true;
          break outer;
        }
      }
    }
    scopeByName[sc.name] = hasQbft ? 'cross' : 'obftOnly';
  });

  const buckets = { cross: {}, obftOnly: {} };
  const groupOrder = { cross: [], obftOnly: [] };
  data.scenarios.forEach((sc) => {
    const scope = scopeByName[sc.name];
    const group = sc.group || 'Other';
    if (!buckets[scope][group]) {
      buckets[scope][group] = [];
      groupOrder[scope].push(group);
    }
    buckets[scope][group].push(sc);
  });
  return { buckets, groupOrder };
}

// ---- top-level scaffolding -------------------------------------------

function renderHeader(data) {
  const header = h('header', { class: 'page', id: 'top' });
  header.appendChild(h('h1', {}, data.title));
  if (data.description) {
    const lead = h('p', { class: 'lead' });
    lead.innerHTML = formatDescription(data.description);
    header.appendChild(lead);
  }
  const pills = h('div', { class: 'summary-pills' });
  pills.appendChild(makePill('Iterations per cell', String(data.iterations)));
  pills.appendChild(makePill('Total wallclock', formatWallclock(data.wallclock)));
  pills.appendChild(makePill('Generated', data.generatedAt));
  pills.appendChild(makePill('Sweeps', String(data.sweeps.length)));
  pills.appendChild(makePill('Scenarios', String(data.scenarios.length)));
  pills.appendChild(makePill('Protocols', data.protocols.join(' · ')));
  header.appendChild(pills);
  return header;
}

function makePill(label, value) {
  return h(
    'div',
    { class: 'pill' },
    h('span', { class: 'label' }, label),
    h('span', { class: 'value' }, value),
  );
}

// renderTOC builds the sticky nav with two rows:
//   1. Sweep row — one link per sweep, always visible. The active sweep
//      is highlighted dynamically (see setupActiveTOC).
//   2. Sub-row   — group anchors for the active sweep, rebuilt on scroll.
//      Hidden until a sweep is in view.
function renderTOC(data) {
  const nav = h('nav', { class: 'toc' });
  const sweepRow = h('div', { class: 'toc-row sweeps' });
  data.sweeps.forEach((sw) => {
    sweepRow.appendChild(
      h('a', { href: `#sweep-${sw.name}`, 'data-sweep': sw.name }, sw.title || sw.name),
    );
  });
  nav.appendChild(sweepRow);
  // Sub-row is populated dynamically once the page is laid out and the
  // observer fires; start with a placeholder div to reserve space.
  nav.appendChild(h('div', { class: 'toc-row groups', 'data-active-sweep': '' }));
  return nav;
}

function renderSweepSection(sweep, data, bucketing) {
  const section = h('section', { class: 'sweep', id: `sweep-${sweep.name}` });
  const head = h('div', { class: 'sweep-head' });
  head.appendChild(h('h2', {}, sweep.title || sweep.name));
  if (sweep.description) {
    const desc = h('p', { class: 'desc' });
    desc.innerHTML = formatDescription(sweep.description);
    head.appendChild(desc);
  }
  section.appendChild(head);

  packsBySweep[sweep.name] = [];
  renderScope(section, sweep, data, bucketing, 'cross', 'Cross-protocol comparison', data.protocols);
  renderScope(section, sweep, data, bucketing, 'obftOnly', 'OBFT-only scenarios', ['OBFT']);

  return section;
}

function renderScope(section, sweep, data, bucketing, scopeKey, scopeLabel, protocols) {
  const groups = bucketing.groupOrder[scopeKey];
  if (groups.length === 0) return;
  const isObftOnly = scopeKey === 'obftOnly';
  section.appendChild(
    h(
      'div',
      { class: `scope-heading ${isObftOnly ? 'obft-only' : 'cross'}` },
      scopeLabel,
    ),
  );
  groups.forEach((group, idx) => {
    const scenarios = bucketing.buckets[scopeKey][group];
    // Default-open the very first pack of each sweep (Cross-protocol
    // Baseline); everything else starts collapsed for a calmer page.
    const open = scopeKey === 'cross' && idx === 0;
    renderGroupPack(section, sweep, scopeKey, group, scenarios, protocols, open);
  });
}

function renderGroupPack(section, sweep, scopeKey, group, scenarios, protocols, open) {
  const packID = `${sweep.name}_${scopeKey}_${slugify(group)}`;
  const isTrend = sweep.points.length > 1;
  const details = h('details', {
    class: `group-pack ${isTrend ? 'trend' : 'detail'} ${scopeKey === 'obftOnly' ? 'obft-only' : ''}`,
    id: `pack-${packID}`,
  });
  if (open) details.setAttribute('open', '');

  const summary = h('summary');
  summary.appendChild(h('span', { class: 'group-name' }, group));
  summary.appendChild(
    h('span', { class: 'group-count' }, `${scenarios.length} scenario${scenarios.length !== 1 ? 's' : ''}`),
  );
  details.appendChild(summary);

  const body = h('div', { class: `group-body ${isTrend ? 'trend' : 'detail'}` });
  if (isTrend) {
    renderGroupTrend(body, sweep, scenarios, protocols, packID);
  } else {
    renderGroupDetail(body, sweep, scenarios, protocols, packID);
  }
  details.appendChild(body);

  section.appendChild(details);
  packsBySweep[sweep.name].push({ id: `pack-${packID}`, label: group, scope: scopeKey });
}

// ---- detail layout (1-point sweep) -----------------------------------
//
// Each group renders ONE interactive chart driven by the matrix:
//   - Summary matrix with clickable rows; first row selected by default.
//   - Bar chart below shows decision-time P50/P90/P99 (in ms) for the
//     selected scenario, with one bar group per protocol.
// Success rate is NOT redrawn in chart form — it's already in the matrix.

function renderGroupDetail(section, sweep, scenarios, protocols, packID) {
  const point = sweep.points[0];
  const initial = scenarios[0];

  const table = renderSummaryMatrix(point, scenarios, protocols);
  section.appendChild(table);

  const wrap = h('div', { class: 'chart-wrap' });
  const canvas = h('canvas', { id: `${packID}_chart` });
  wrap.appendChild(canvas);
  section.appendChild(wrap);

  chartInits.push(() => {
    const chart = buildLatencyChart(canvas, point, protocols, initial);
    chartInstances.push(chart);
    wireMatrixSelection(table, scenarios, initial, (sc) => {
      updateLatencyChart(chart, point, protocols, sc);
    });
  });
}

// renderCell renders one numeric matrix cell as two stacked spans
// (success% on the left, "P99 Xms" on the right) so the columns line up
// across rows. Returns the <td> element.
function renderCell(cell) {
  if (!cell || cell.iterations === 0) {
    return h('td', { class: 'na' }, 'n/a');
  }
  let cls = 'ok';
  if (cell.successRate < 0.5) cls = 'miss';
  else if (cell.successRate < 1.0) cls = 'warn';
  const p99 = cell.decisionTime ? Math.round(cell.decisionTime.p99) : 0;
  return h(
    'td',
    { class: cls },
    h('span', { class: 'pct' }, `${Math.round(cell.successRate * 100)}%`),
    h('span', { class: 'lat' }, `P99 ${p99} ms`),
  );
}

function renderSummaryMatrix(point, scenarios, protocols) {
  const table = h('table', { class: 'matrix' });
  const headerRow = h('tr', {}, h('th', {}, 'Scenario'));
  protocols.forEach((p) => headerRow.appendChild(h('th', {}, p)));
  table.appendChild(h('thead', {}, headerRow));

  const tbody = h('tbody');
  scenarios.forEach((sc) => {
    const row = h('tr', { 'data-scenario': sc.name }, h('td', { class: 'scen' }, sc.title));
    protocols.forEach((p) => row.appendChild(renderCell(findCell(point, sc.name, p))));
    tbody.appendChild(row);
  });
  table.appendChild(tbody);
  return table;
}

function buildLatencyChart(canvas, point, protocols, scenario) {
  return new Chart(canvas, {
    type: 'bar',
    data: latencyChartData(point, protocols, scenario),
    options: {
      responsive: true,
      maintainAspectRatio: false,
      scales: {
        y: {
          title: { display: true, text: 'decision time (ms)' },
          grid: { color: 'rgba(15, 23, 42, 0.06)' },
          ticks: { padding: 6 },
        },
        x: {
          title: { display: false },
          grid: { display: false },
          ticks: { padding: 4 },
        },
      },
      plugins: {
        legend: { position: 'top', align: 'end' },
        tooltip: {
          callbacks: {
            title: (items) => items[0] ? items[0].label : '',
            label: (ctx) => `${ctx.dataset.label}: ${Math.round(ctx.parsed.y)} ms`,
          },
        },
      },
    },
  });
}

function latencyChartData(point, protocols, scenario) {
  return {
    labels: ['P50', 'P90', 'P99'],
    datasets: protocols.map((p) => {
      const cell = findCell(point, scenario.name, p);
      const data = cell && cell.decisionTime
        ? [cell.decisionTime.p50, cell.decisionTime.p90, cell.decisionTime.p99]
        : [null, null, null];
      return {
        label: p,
        backgroundColor: protocolColor(p),
        borderColor: protocolColor(p),
        data,
      };
    }),
  };
}

function updateLatencyChart(chart, point, protocols, scenario) {
  const d = latencyChartData(point, protocols, scenario);
  chart.data.labels = d.labels;
  chart.data.datasets = d.datasets;
  chart.options.plugins.title.text = scenario.title;
  chart.update();
}

// ---- trend layout (multi-point sweep) --------------------------------
//
// Each group renders ONE interactive line chart driven by a per-axis
// matrix. The chart plots P99 decision time vs swept axis for the
// selected scenario, with one line per protocol.

function renderGroupTrend(section, sweep, scenarios, protocols, packID) {
  const initial = scenarios[0];

  const table = renderTrendMatrix(sweep, scenarios, protocols);
  section.appendChild(table);

  const wrap = h('div', { class: 'chart-wrap' });
  const canvas = h('canvas', { id: `${packID}_chart` });
  wrap.appendChild(canvas);
  section.appendChild(wrap);

  chartInits.push(() => {
    const chart = buildTrendLineChart(canvas, sweep, protocols, initial);
    chartInstances.push(chart);
    wireMatrixSelection(table, scenarios, initial, (sc) => {
      updateTrendLineChart(chart, sweep, protocols, sc);
    });
  });
}

function renderTrendMatrix(sweep, scenarios, protocols) {
  const table = h('table', { class: 'matrix trend' });
  const headerRow = h('tr', {}, h('th', {}, 'Scenario'));
  sweep.points.forEach((pt) => headerRow.appendChild(h('th', {}, pt.label)));
  table.appendChild(h('thead', {}, headerRow));

  const tbody = h('tbody');
  scenarios.forEach((sc) => {
    const row = h('tr', { 'data-scenario': sc.name }, h('td', { class: 'scen' }, sc.title));
    sweep.points.forEach((pt) => {
      const td = h('td', { class: 'point' });
      protocols.forEach((p) => {
        const cell = findCell(pt, sc.name, p);
        const line = h('div', { class: 'cell-line' });
        line.appendChild(h('span', { class: 'proto' }, `${p}:`));
        if (!cell || cell.iterations === 0) {
          line.classList.add('na');
          line.appendChild(h('span', { class: 'pct' }, 'n/a'));
        } else {
          let cls = 'ok';
          if (cell.successRate < 0.5) cls = 'miss';
          else if (cell.successRate < 1.0) cls = 'warn';
          line.classList.add(cls);
          const p99 = cell.decisionTime ? Math.round(cell.decisionTime.p99) : 0;
          line.appendChild(h('span', { class: 'pct' }, `${Math.round(cell.successRate * 100)}%`));
          line.appendChild(h('span', { class: 'lat' }, `${p99} ms`));
        }
        td.appendChild(line);
      });
      row.appendChild(td);
    });
    tbody.appendChild(row);
  });
  table.appendChild(tbody);
  return table;
}

function buildTrendLineChart(canvas, sweep, protocols, scenario) {
  return new Chart(canvas, {
    type: 'line',
    data: trendLineChartData(sweep, protocols, scenario),
    options: {
      responsive: true,
      maintainAspectRatio: false,
      interaction: { mode: 'nearest', intersect: false },
      scales: {
        x: {
          title: { display: true, text: sweep.axisLabel || '' },
          grid: { display: false },
          ticks: { padding: 4 },
        },
        y: {
          title: { display: true, text: 'P99 decision time (ms)' },
          grid: { color: 'rgba(15, 23, 42, 0.06)' },
          ticks: { padding: 6 },
        },
      },
      plugins: {
        legend: { position: 'top', align: 'end' },
        tooltip: {
          callbacks: {
            title: (items) => (items[0] ? `${sweep.axisLabel || 'point'}: ${items[0].label}` : ''),
            label: (ctx) => `${ctx.dataset.label}: P99 ${Math.round(ctx.parsed.y)} ms`,
          },
        },
      },
    },
  });
}

function trendLineChartData(sweep, protocols, scenario) {
  return {
    labels: sweep.points.map((pt) => pt.label),
    datasets: protocols.map((p) => {
      const data = sweep.points.map((pt) => {
        const cell = findCell(pt, scenario.name, p);
        if (!cell || cell.iterations === 0 || !cell.decisionTime) return null;
        return cell.decisionTime.p99;
      });
      return {
        label: p,
        borderColor: protocolColor(p),
        backgroundColor: protocolColor(p),
        pointStyle: protocolPointStyle(p),
        spanGaps: true,
        fill: false,
        tension: 0.15,
        borderDash: protocolDash(p),
        data,
      };
    }),
  };
}

function updateTrendLineChart(chart, sweep, protocols, scenario) {
  const d = trendLineChartData(sweep, protocols, scenario);
  chart.data.labels = d.labels;
  chart.data.datasets = d.datasets;
  chart.options.plugins.title.text = scenario.title;
  chart.update();
}

// ---- shared: matrix → chart wiring -----------------------------------

// wireMatrixSelection adds click handlers to every <tbody> row in `table`,
// highlighting the clicked row with .selected and invoking onSelect with
// the corresponding scenario. The row for `initial` starts pre-selected.
function wireMatrixSelection(table, scenarios, initial, onSelect) {
  const byName = new Map();
  scenarios.forEach((sc) => byName.set(sc.name, sc));
  const rows = table.querySelectorAll('tbody tr');
  rows.forEach((row) => {
    const sname = row.getAttribute('data-scenario');
    if (sname === initial.name) row.classList.add('selected');
    row.addEventListener('click', () => {
      const sc = byName.get(sname);
      if (!sc) return;
      rows.forEach((r) => r.classList.remove('selected'));
      row.classList.add('selected');
      onSelect(sc);
    });
  });
}

// ---- helpers ---------------------------------------------------------

// h(tag, attrs, ...children) — small DOM builder. attrs are setAttribute'd
// (except 'class', which sets className). Children may be strings (wrapped
// as text nodes), DOM nodes, or null/undefined (skipped).
function h(tag, attrs, ...children) {
  const el = document.createElement(tag);
  if (attrs) {
    Object.entries(attrs).forEach(([k, v]) => {
      if (k === 'class') el.className = v;
      else el.setAttribute(k, v);
    });
  }
  children.flat().forEach((c) => {
    if (c == null) return;
    if (typeof c === 'string' || typeof c === 'number') {
      el.appendChild(document.createTextNode(String(c)));
    } else {
      el.appendChild(c);
    }
  });
  return el;
}

function makeCanvas(id, initFn) {
  const wrap = h('div', { class: 'chart-wrap' });
  const canvas = h('canvas', { id });
  wrap.appendChild(canvas);
  chartInits.push(() => {
    const inst = initFn(canvas);
    if (inst) chartInstances.push(inst);
  });
  return wrap;
}

// findCell — linear scan; fine at the matrix sizes the framework targets.
function findCell(point, scenarioName, protocolName) {
  return point.cells.find((c) => c.scenario === scenarioName && c.protocol === protocolName) || null;
}

function protocolColor(name) {
  return PROTOCOL_COLORS[name] || '#888';
}

function protocolDash(name) {
  return name === 'OBFT' ? [] : [6, 4];
}

function protocolPointStyle(name) {
  switch (name) {
    case 'OBFT':
      return 'circle';
    case 'QBFT':
      return 'triangle';
    default:
      return 'rect';
  }
}

// slugify converts a human-readable group label to a DOM-safe slug.
// Used to build canvas IDs like `canonical_cross_silent_operators_success`.
function slugify(s) {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
}

// setupActiveTOC wires the sticky nav's two rows to scroll position via
// a scroll listener (IntersectionObserver was less reliable in headless
// preview environments — sticking with the simpler approach):
//   - Top row: highlight the sweep section whose top is just above the
//     viewport's 25%-from-top probe point.
//   - Sub-row: rebuild on every active-sweep change to list that sweep's
//     group anchors; highlight the pack whose top is similarly near the
//     probe.
function setupActiveTOC(data) {
  const sweepLinks = new Map();
  document.querySelectorAll('nav.toc .toc-row.sweeps a[data-sweep]').forEach((a) => {
    sweepLinks.set(a.getAttribute('data-sweep'), a);
  });
  const subRow = document.querySelector('nav.toc .toc-row.groups');
  if (!subRow || sweepLinks.size === 0) return;

  let activeSweep = data.sweeps[0]?.name;
  let activePack = null;

  const rebuildSubRow = (sweepName) => {
    subRow.innerHTML = '';
    subRow.setAttribute('data-active-sweep', sweepName);
    (packsBySweep[sweepName] || []).forEach((pack) => {
      subRow.appendChild(
        h(
          'a',
          { href: `#${pack.id}`, class: pack.scope === 'obftOnly' ? 'obft-only' : 'cross' },
          pack.label,
        ),
      );
    });
    if (activePack) markPackActive(activePack);
  };
  const markSweepActive = (name) => {
    if (activeSweep === name) return;
    activeSweep = name;
    sweepLinks.forEach((a, n) => a.classList.toggle('active', n === name));
    rebuildSubRow(name);
  };
  const markPackActive = (id) => {
    activePack = id;
    subRow.querySelectorAll('a').forEach((a) => {
      a.classList.toggle('active', a.getAttribute('href') === `#${id}`);
    });
  };

  // Initial render.
  rebuildSubRow(activeSweep);
  sweepLinks.get(activeSweep)?.classList.add('active');

  // Probe is at 25% of viewport height from the top — far enough below
  // the sticky TOC that "what section am I reading" maps to the section
  // whose top is at-or-above the probe.
  const detectActive = () => {
    const probeY = window.scrollY + window.innerHeight * 0.25;
    const sections = document.querySelectorAll('section.sweep');
    let active = sections[0];
    sections.forEach((s) => {
      if (s.offsetTop <= probeY) active = s;
    });
    if (active) markSweepActive(active.id.replace(/^sweep-/, ''));

    const packs = document.querySelectorAll('details.group-pack');
    let activeP = null;
    packs.forEach((p) => {
      if (p.offsetTop <= probeY) activeP = p;
    });
    if (activeP) markPackActive(activeP.id);
  };

  let scrollPending = false;
  const onScroll = () => {
    if (scrollPending) return;
    scrollPending = true;
    setTimeout(() => {
      scrollPending = false;
      detectActive();
    }, 60);
  };
  window.addEventListener('scroll', onScroll, { passive: true });
  // Also run once after initial layout in case the page loaded scrolled.
  detectActive();
}

// escapeHtml escapes the five HTML special chars. Used before injecting
// strings into innerHTML so user-controlled text (descriptions etc.)
// can't smuggle in markup.
function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, (ch) => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;',
  })[ch]);
}

// formatDescription HTML-escapes the input, then wraps three families
// of tokens in <strong> for visual emphasis:
//
//   1. Set literals like `{4, 7, 10, 13}` or `{0.1, 0.3, 0.5, 0.7}`.
//   2. Parameter assignments like `n=4`, `BTT=200ms`, `Sigma=0.30`,
//      `LossRate=0.10`, `BurstFactor=5`, `Median=BTT/2`, `K=4`.
//   3. Known network-model names: ConstantDelay / LogNormalDelay /
//      LossyNetwork / PerReceiverDelay / CorrelatedLinkDelay /
//      JitteredDelay. These name the operating-point's network shape
//      and deserve to stand out.
//
// The result is an HTML fragment suitable for innerHTML.
function formatDescription(text) {
  const networkModels = '(?:ConstantDelay|LogNormalDelay|LossyNetwork|PerReceiverDelay|CorrelatedLinkDelay|JitteredDelay)';
  let out = escapeHtml(text);
  // Order matters: set literals first (they may contain '=') ... actually
  // sets don't contain '=', so order is fine either way. Bold each family
  // in turn with a unique pattern.
  const patterns = [
    /\{[^}]+\}/g, // sets like {4, 7, 10, 13}
    /\b[A-Za-z][A-Za-z_0-9]*=[A-Za-z0-9./_]+(?:ms|s)?\b/g, // param=value
    new RegExp('\\b' + networkModels + '\\b', 'g'), // network model names
  ];
  patterns.forEach((re) => {
    out = out.replace(re, (m) => `<strong>${m}</strong>`);
  });
  return out;
}

// formatWallclock strips subsecond decimals from Go's Duration.String()
// output for readability: "2m41.872825333s" → "2m41s".
function formatWallclock(s) {
  return String(s).replace(/\.\d+s/g, 's');
}
